create table if not exists public.prescription_refills(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,prescription_id bigint not null references public.prescriptions(id) on delete cascade,refill_number integer not null default 1,refill_date date not null default current_date,quantity_dispensed integer not null default 0,dispensed_by uuid references public.app_users(id) on delete set null,sale_id bigint references public.sales(id) on delete set null,status text not null default 'completed',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,prescription_id,refill_number));
alter table public.prescription_refills enable row level security; revoke all on public.prescription_refills from anon,authenticated; grant select,insert,update,delete on public.prescription_refills to authenticated;
create policy prescription_refills_tenant on public.prescription_refills for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create or replace function private.enforce_prescription_refill_business() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from prescriptions p where p.id=new.prescription_id and p.business_id=new.business_id) then raise exception 'prescription does not belong to business'; end if; if new.sale_id is not null and not exists(select 1 from sales s where s.id=new.sale_id and s.business_id=new.business_id) then raise exception 'sale does not belong to business'; end if; if new.quantity_dispensed<0 then raise exception 'invalid refill quantity'; end if; return new; end$$;
revoke all on function private.enforce_prescription_refill_business() from public,anon,authenticated;
create trigger trg_prescription_refill_business before insert or update on public.prescription_refills for each row execute function private.enforce_prescription_refill_business();
create trigger trg_prescription_refills_updated_at before update on public.prescription_refills for each row execute function public.touch_updated_at();